{"aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "config": {
    "kibana": {
      "hideWarnings": true,
      "renderer": "svg"
    },
    "text": {
      "baseline": "middle",
      "fill": "#343741",
      "font": "Inter UI, -apple-system, BlinkMacSystemFont, Segoe UI, Helvetica, Arial, sans-serif",
      "fontSize": 14
    }
  },
  "data": [
    {
      "format": {
        "property": "aggregations.s.a.buckets"
      },
      "name": "src",
      "transform": [
        {
          "as": "agent",
          "expr": "datum.key",
          "type": "formula"
        },
        {
          "as": "src",
          "expr": "datum.last.hits.hits[0]._source",
          "type": "formula"
        },
        {
          "as": "when",
          "expr": "timeFormat(toDate(datum.src.timestamp), '%Y-%m-%d %H:%M')",
          "type": "formula"
        },
        {
          "as": "c0",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.state) ? '' + datum.src.data.yara.state : '-'",
          "type": "formula"
        },
        {
          "as": "c1",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.yr) ? '' + datum.src.data.yara.yr : '-'",
          "type": "formula"
        },
        {
          "as": "c2",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.rules_name) ? '' + datum.src.data.yara.rules_name : '-'",
          "type": "formula"
        },
        {
          "as": "c3",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.rules_age) ? '' + datum.src.data.yara.rules_age : '-'",
          "type": "formula"
        },
        {
          "as": "c4",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.scans) ? '' + datum.src.data.yara.scans : '-'",
          "type": "formula"
        },
        {
          "as": "c5",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.errors) ? '' + datum.src.data.yara.errors : '-'",
          "type": "formula"
        },
        {
          "as": "c6",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.hits) ? '' + datum.src.data.yara.hits : '-'",
          "type": "formula"
        },
        {
          "as": "c7",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.quarantine) ? '' + datum.src.data.yara.quarantine : '-'",
          "type": "formula"
        },
        {
          "as": "c8",
          "expr": "(datum.src.data && datum.src.data.yara && datum.src.data.yara.problem) ? '' + datum.src.data.yara.problem : '-'",
          "type": "formula"
        }
      ],
      "url": {
        "body": {
          "aggs": {
            "s": {
              "aggs": {
                "a": {
                  "aggs": {
                    "last": {
                      "top_hits": {
                        "_source": {
                          "includes": [
                            "data.yara.state",
                            "data.yara.yr",
                            "data.yara.rules_name",
                            "data.yara.rules_age",
                            "data.yara.scans",
                            "data.yara.errors",
                            "data.yara.hits",
                            "data.yara.quarantine",
                            "data.yara.problem",
                            "timestamp",
                            "rule.level"
                          ]
                        },
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ]
                      }
                    }
                  },
                  "terms": {
                    "field": "agent.name",
                    "size": 500
                  }
                }
              },
              "filter": {
                "term": {
                  "rule.groups": "yara_status"
                }
              }
            }
          },
          "query": {
            "bool": {
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "query_string": {
                    "analyze_wildcard": true,
                    "query": "rule.id:[133400 TO 133499] AND rule.id:/[0-9]{6}/"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "size": 0
        },
        "index": "wazuh-alerts-*"
      }
    },
    {
      "name": "rows",
      "source": "src",
      "transform": [
        {
          "as": [
            "row0"
          ],
          "ops": [
            "row_number"
          ],
          "sort": {
            "field": {
              "signal": "sortField"
            },
            "order": {
              "signal": "sortDesc ? 'descending' : 'ascending'"
            }
          },
          "type": "window"
        },
        {
          "as": "row",
          "expr": "datum.row0 - 1",
          "type": "formula"
        },
        {
          "expr": "datum.row < floor((height - 38) / 34)",
          "type": "filter"
        }
      ]
    },
    {
      "name": "head",
      "values": [
        {
          "align": "left",
          "i": 0,
          "key": "agent",
          "label": "代理程式",
          "num": false,
          "pl": 0,
          "pr": 10,
          "right": false
        },
        {
          "align": "left",
          "i": 1,
          "key": "c0",
          "label": "狀態",
          "num": false,
          "pl": 12,
          "pr": 10,
          "right": false
        },
        {
          "align": "left",
          "i": 2,
          "key": "c1",
          "label": "yr",
          "num": false,
          "pl": 12,
          "pr": 10,
          "right": false
        },
        {
          "align": "left",
          "i": 3,
          "key": "c2",
          "label": "規則",
          "num": false,
          "pl": 12,
          "pr": 10,
          "right": false
        },
        {
          "align": "right",
          "i": 4,
