          "label": "規則天數",
          "num": true,
          "pl": 12,
          "pr": 10,
          "right": true
        },
        {
          "align": "right",
          "i": 5,
          "key": "c4",
          "label": "掃描",
          "num": true,
          "pl": 12,
          "pr": 10,
          "right": true
        },
        {
          "align": "right",
          "i": 6,
          "key": "c5",
          "label": "失敗",
